<?php
require_once 'database.php';require_once 'functions.php';session_start();require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$report=(int)($_POST['report']??0);if($report){$q=$db->prepare("UPDATE reports SET status='resolved',resolved_at=CURRENT_TIMESTAMP WHERE id=?");$q->execute([$report]);}}
$q=$db->query("SELECT r.*,ru.username AS reporter_name,tu.username AS reported_name FROM reports r JOIN users ru ON ru.id=r.reporter_id JOIN users tu ON tu.id=r.reported_id ORDER BY CASE WHEN r.status='open' THEN 0 ELSE 1 END,r.created_at DESC");$reports=$q->fetchAll(PDO::FETCH_ASSOC);$open=0;foreach($reports as $r)if($r['status']==='open')$open++;
layout_start('Admin');echo '<div class="admin-head"><div><h1>Moderation</h1><p class="muted">Review profile reports and keep the community safe.</p></div><div class="stat"><b>'.count($reports).'</b><span>Total reports</span></div><div class="stat"><b>'.$open.'</b><span>Open reports</span></div></div><div class="admin-list">';if(!$reports)echo '<div class="card info"><p class="muted">No reports yet.</p></div>';foreach($reports as $r){$status=$r['status']==='open'?'<span class="status open">Open</span>':'<span class="status">Resolved</span>';echo '<article class="card report-card"><div class="report-meta"><h2>'.h($r['reported_name']).' '.$status.'</h2><small>Reported by '.h($r['reporter_name']).' · '.h($r['created_at']).'</small></div><p><b>Reason:</b> '.h($r['reason']).'</p><p>'.nl2br(h($r['details'])).'</p>';if($r['status']==='open')echo '<form method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="report" value="'.$r['id'].'"><button class="btn">Mark Resolved</button></form>';echo '</article>';}echo '</div>';layout_end();
